-- Every catalogue entry exposes the same synonym data shape, even when no safe direct synonym exists.
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('[]')) WHERE is_catalog=1 AND json_type(details_json,'$.synonyms') IS NULL;
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonymNotes',json('[]')) WHERE is_catalog=1 AND json_type(details_json,'$.synonymNotes') IS NULL;

