UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["advantageous"]'),'$.synonymNotes',json('[{"term":"advantageous","nuance":"Both mean producing benefit; “advantageous” often implies giving an advantage relative to alternatives and is more formal.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='beneficial';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["condition"]'),'$.synonymNotes',json('[{"term":"condition","nuance":"A “condition” can be one factor/state; “circumstances” usually refers to the surrounding facts that shape a situation.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='circumstance';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["result"]'),'$.synonymNotes',json('[{"term":"result","nuance":"A “result” is any outcome; “consequence” often suggests an outcome caused by an action and can carry a negative implication.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='consequence';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["substantial"]'),'$.synonymNotes',json('[{"term":"substantial","nuance":"Both mean large/important; “substantial” can imply solid, significant amount or importance and is often slightly stronger.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='considerable';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["persuade"]'),'$.synonymNotes',json('[{"term":"persuade","nuance":"“Convince” changes what someone believes; “persuade” usually gets someone to do something. They overlap but take different complements.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='convince';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["decrease"]'),'$.synonymNotes',json('[{"term":"decrease","nuance":"Both can mean become less; “decline” can suggest a gradual downward trend and also means politely refuse.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='decline';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["require"]'),'$.synonymNotes',json('[{"term":"require","nuance":"“Require” states a necessity; “demand” is stronger and can imply insisting forcefully.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='demand';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["effective"]'),'$.synonymNotes',json('[{"term":"effective","nuance":"“Effective” means achieving the result; “efficient” means achieving it with little waste of time/resources. Something can be effective but inefficient.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='efficient';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["highlight"]'),'$.synonymNotes',json('[{"term":"highlight","nuance":"Both draw attention to importance; “emphasise” stresses importance, while “highlight” can simply make something noticeable.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='emphasise';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["set up"]'),'$.synonymNotes',json('[{"term":"set up","nuance":"“Set up” is the everyday equivalent for creating an organisation/system; “establish” is more formal and can also prove a fact.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='establish';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["assess"]'),'$.synonymNotes',json('[{"term":"assess","nuance":"Both mean judge quality/value; “evaluate” often implies forming an overall judgement, while “assess” can focus on measuring against criteria.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='evaluate';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["proof"]'),'$.synonymNotes',json('[{"term":"proof","nuance":"“Proof” is stronger: it establishes something conclusively; “evidence” supports a claim but may not prove it by itself.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='evidence';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["element"]'),'$.synonymNotes',json('[{"term":"element","nuance":"Both can mean a contributing part; “factor” stresses something that influences a result.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='factor';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["adaptable"]'),'$.synonymNotes',json('[{"term":"adaptable","nuance":"“Adaptable” describes ability to adjust to change; “flexible” can describe plans/rules that can be changed as well as people.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='flexible';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["effect"]'),'$.synonymNotes',json('[{"term":"effect","nuance":"Both mean a result or influence; “impact” often suggests a strong/notable effect and is slightly more emphatic.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='impact';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["preserve"]'),'$.synonymNotes',json('[{"term":"preserve","nuance":"“Preserve” means protect from change/loss; “maintain” means keep something at the same level/condition through continued effort.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='maintain';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["apparent"]'),'$.synonymNotes',json('[{"term":"apparent","nuance":"“Obvious” means very easy to see/understand; “apparent” can mean seeming to be true and is often less certain.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='obvious';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["possibility"]'),'$.synonymNotes',json('[{"term":"possibility","nuance":"“Potential” is latent capacity for future development; “possibility” is simply something that may happen/be true.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='potential';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["main concern"]'),'$.synonymNotes',json('[{"term":"main concern","nuance":"A priority is something given importance before others; “main concern” is close but does not always imply ordering/actions.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='priority';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["dependable"]'),'$.synonymNotes',json('[{"term":"dependable","nuance":"They are often interchangeable for people/things that can be trusted; “reliable” is also common for data, methods and sources.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='reliable';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["important"]'),'$.synonymNotes',json('[{"term":"important","nuance":"Both can mean important; “significant” can also mean large enough to matter or statistically meaningful, so it is more precise in formal writing.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='significant';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["plan"]'),'$.synonymNotes',json('[{"term":"plan","nuance":"A “plan” states intended actions; a “strategy” is an organised longer-term approach for achieving an objective.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='strategy';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["inclination"]'),'$.synonymNotes',json('[{"term":"inclination","nuance":"“Inclination” often describes a person’s preference; “tendency” can describe repeated patterns in people, data or events.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='tendency';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["differ"]'),'$.synonymNotes',json('[{"term":"differ","nuance":"“Differ” compares things as not the same; “vary” often means change across time/cases or show a range of differences.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='vary';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["recognise"]'),'$.synonymNotes',json('[{"term":"recognise","nuance":"“Be aware of” means know about/notice; “recognise” can mean identify something or acknowledge its importance/truth.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='be aware of';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["conduct"]'),'$.synonymNotes',json('[{"term":"conduct","nuance":"Both can mean perform a task/research; “conduct” is more formal and especially common with studies, tests and investigations.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='carry out';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["consider"]'),'$.synonymNotes',json('[{"term":"consider","nuance":"They are close; “take into account” specifically means include a factor in a decision/judgement, while “consider” has broader meanings.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='take into account';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["by comparison"]'),'$.synonymNotes',json('[{"term":"by comparison","nuance":"Both introduce comparison; “in contrast” explicitly highlights difference, while “by comparison” can lead to either similarity or difference.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='in contrast';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["increase understanding"]'),'$.synonymNotes',json('[{"term":"increase understanding","nuance":"Both describe making people more conscious of an issue; “raise awareness” is the standard collocation in campaigns/public communication.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='raise awareness';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["unclear"]'),'$.synonymNotes',json('[{"term":"unclear","nuance":"“Unclear” is general; “ambiguous” specifically means having two or more possible interpretations.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='ambiguous';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["expect"]'),'$.synonymNotes',json('[{"term":"expect","nuance":"Both look ahead; “anticipate” often includes preparing for what is expected and is more formal.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='anticipate';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["logical"]'),'$.synonymNotes',json('[{"term":"logical","nuance":"“Logical” describes sound reasoning/order; “coherent” stresses that parts connect clearly into a unified whole.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='coherent';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["convincing"]'),'$.synonymNotes',json('[{"term":"convincing","nuance":"Both can persuade; “compelling” is usually stronger and can also mean powerfully interesting or demanding attention.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='compelling';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["thorough"]'),'$.synonymNotes',json('[{"term":"thorough","nuance":"“Thorough” means done carefully and completely; “comprehensive” means covering all or nearly all relevant parts.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='comprehensive';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["admit"]'),'$.synonymNotes',json('[{"term":"admit","nuance":"Both can accept something is true; “concede” often means reluctantly acknowledging a point in an argument.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='concede';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["contentious"]'),'$.synonymNotes',json('[{"term":"contentious","nuance":"Both describe something causing disagreement; “contentious” is more formal and often focuses on active dispute.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='controversial';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["believable"]'),'$.synonymNotes',json('[{"term":"believable","nuance":"Both mean able to be believed; “credible” is more formal and commonly evaluates sources, evidence and claims.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='credible';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["worsen"]'),'$.synonymNotes',json('[{"term":"worsen","nuance":"These are close; “deteriorate” is more formal and often suggests gradual worsening in condition or quality.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='deteriorate';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["differentiate"]'),'$.synonymNotes',json('[{"term":"differentiate","nuance":"Both mean recognise/show differences; “differentiate” is more formal/technical, while “distinguish” also means recognise distinctly.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='distinguish';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["improve"]'),'$.synonymNotes',json('[{"term":"improve","nuance":"Both mean make better; “enhance” often means increase an existing positive quality and is more formal.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='enhance';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["practical"]'),'$.synonymNotes',json('[{"term":"practical","nuance":"“Feasible” means possible to do successfully; “practical” can also mean sensible/useful in real conditions, not just possible.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='feasible';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["essential"]'),'$.synonymNotes',json('[{"term":"essential","nuance":"“Essential” means absolutely necessary; “fundamental” means basic/core and may describe a foundational principle.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='fundamental';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["unavoidable"]'),'$.synonymNotes',json('[{"term":"unavoidable","nuance":"They are close; “inevitable” means certain to happen, while “unavoidable” stresses that it cannot be prevented/escaped.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='inevitable';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["defend"]'),'$.synonymNotes',json('[{"term":"defend","nuance":"“Defend” supports/protects a position; “justify” specifically provides reasons showing an action/claim is reasonable or right.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='justify';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["insignificant"]'),'$.synonymNotes',json('[{"term":"insignificant","nuance":"Both mean too small/unimportant to matter; “negligible” is more formal and often used for amounts/effects.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='negligible';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["idea"]'),'$.synonymNotes',json('[{"term":"idea","nuance":"“Idea” is broad and everyday; “notion” is more formal and often means a concept/belief, sometimes one that is vague.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='notion';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["impartial"]'),'$.synonymNotes',json('[{"term":"impartial","nuance":"As adjectives, both mean not influenced by personal feelings; “objective” also commonly means based on observable facts.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='objective';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["notice"]'),'$.synonymNotes',json('[{"term":"notice","nuance":"“Notice” means become aware of something; “perceive” can also mean interpret/understand something in a particular way.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='perceive';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["believable"]'),'$.synonymNotes',json('[{"term":"believable","nuance":"Both mean seeming possible/true; “plausible” often evaluates an explanation/argument and does not guarantee truth.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='plausible';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["mainly"]'),'$.synonymNotes',json('[{"term":"mainly","nuance":"They are close; “predominantly” is more formal and often used to describe the largest proportion/type.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='predominantly';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["deep"]'),'$.synonymNotes',json('[{"term":"deep","nuance":"“Deep” is broad; “profound” is stronger and formal, describing very great intellectual, emotional or social depth/effect.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='profound';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["strengthen"]'),'$.synonymNotes',json('[{"term":"strengthen","nuance":"Both mean make stronger; “reinforce” often means strengthen something already present, such as a message, structure or behaviour.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='reinforce';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["provisional"]'),'$.synonymNotes',json('[{"term":"provisional","nuance":"Both mean not final; “tentative” can also mean hesitant/uncertain, while “provisional” usually means temporarily arranged.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='tentative';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["weaken"]'),'$.synonymNotes',json('[{"term":"weaken","nuance":"Both mean make less strong; “undermine” often implies a gradual, indirect or hidden weakening of authority, confidence or an argument.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='undermine';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["workable"]'),'$.synonymNotes',json('[{"term":"workable","nuance":"Both mean capable of succeeding; “viable” is more formal and often considers long-term practical/economic survival.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='viable';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["considering"]'),'$.synonymNotes',json('[{"term":"considering","nuance":"They often introduce a reason based on new facts; “in light of” is more formal and common in analytical writing.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='in light of';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["explain"]'),'$.synonymNotes',json('[{"term":"explain","nuance":"When used with reasons, “account for” means explain why something happened; it can also mean constitute a proportion.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='account for';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["cause"]'),'$.synonymNotes',json('[{"term":"cause","nuance":"Both can mean produce a result; “give rise to” is more formal and often used for consequences or developments.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='give rise to';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["clarify"]'),'$.synonymNotes',json('[{"term":"clarify","nuance":"Both make something easier to understand; “shed light on” often means provide new information that clarifies a problem.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='shed light on';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["find a compromise"]'),'$.synonymNotes',json('[{"term":"find a compromise","nuance":"Both involve reconciling competing needs; “strike a balance” does not necessarily require each side to give something up, unlike a compromise.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='strike a balance';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["assume"]'),'$.synonymNotes',json('[{"term":"assume","nuance":"They overlap only in some contexts; “take for granted” often means fail to appreciate something because you assume it will remain available.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='take for granted';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["eventually"]'),'$.synonymNotes',json('[{"term":"eventually","nuance":"Both refer to a later outcome; “in the long run” specifically focuses on the eventual effect over a long period.","interchangeable":false}]')) WHERE is_catalog=1 AND normalized_text='in the long run';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["because"]'),'$.synonymNotes',json('[{"term":"because","nuance":"Both introduce reasons; “on the grounds that” is much more formal and often used for official/argumentative justification.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='on the grounds that';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["mostly"]'),'$.synonymNotes',json('[{"term":"mostly","nuance":"Both mean largely; “to a large extent” is more formal and leaves room for exceptions, useful in balanced arguments.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='to a large extent';
UPDATE vocabulary_items SET details_json=json_set(details_json,'$.synonyms',json('["concerning"]'),'$.synonymNotes',json('[{"term":"concerning","nuance":"Both introduce a topic; “with regard to” is more formal and common in reports/correspondence.","interchangeable":true}]')) WHERE is_catalog=1 AND normalized_text='with regard to';

-- Grammar coverage audit: four additional original topics per stage, bringing every pathway to 12 sections.
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-09','P1-P4',9,'word forms','Possessives & contractions','Use apostrophes for possession and common contractions.','{"rule":"Use apostrophe + s for singular possession, and apostrophes to show omitted letters in contractions.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for possessives & contractions.","Apply possessives & contractions accurately in context.","Edit a common error involving possessives & contractions."]','[{"label":"Accurate","sentence":"Aisha’s bag is beside the door."},{"label":"Needs editing","sentence":"Aishas bag is beside the door."},{"label":"Correction","sentence":"Aisha’s bag is beside the door."}]','["Avoid: Aishas bag is beside the door.","Prefer: Aisha’s bag is beside the door."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-09-a','gram-p1p4-09','P1-P4','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Possessives & contractions”?","options":["Aisha’s bag is beside the door.","Aishas bag is beside the door.","Aishas bag is beside the door.?","Aisha’s bag is beside the door. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["Aisha’s bag is beside the door."]}','{"text":"Use apostrophe + s for singular possession, and apostrophes to show omitted letters in contractions."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-09-b','gram-p1p4-09','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: Aishas bag is beside the door.","modelText":"Aisha’s bag is beside the door.","speakFirst":false}','{"acceptedAnswers":["Aisha’s bag is beside the door."],"modelAnswer":"Aisha’s bag is beside the door."}','{"text":"Use apostrophe + s for singular possession, and apostrophes to show omitted letters in contractions."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-10','P1-P4',10,'description','Adverbs: how, when & where','Add clear information about actions without confusing adjective and adverb forms.','{"rule":"Use adverbs to tell how, when or where an action happens; many manner adverbs end in -ly.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for adverbs: how, when & where.","Apply adverbs: how, when & where accurately in context.","Edit a common error involving adverbs: how, when & where."]','[{"label":"Accurate","sentence":"The class listened quietly during the story."},{"label":"Needs editing","sentence":"The class listened quiet during the story."},{"label":"Correction","sentence":"The class listened quietly during the story."}]','["Avoid: The class listened quiet during the story.","Prefer: The class listened quietly during the story."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-10-a','gram-p1p4-10','P1-P4','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Adverbs: how, when & where”?","options":["The class listened quietly during the story.","The class listened quiet during the story.","The class listened quiet during the story.?","The class listened quietly during the story. Extra."],"audioText":"The class listened quietly during the story."}','{"correctOption":0,"acceptedAnswers":["The class listened quietly during the story."]}','{"text":"Use adverbs to tell how, when or where an action happens; many manner adverbs end in -ly."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-10-b','gram-p1p4-10','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: The class listened quiet during the story.","modelText":"The class listened quietly during the story.","speakFirst":false}','{"acceptedAnswers":["The class listened quietly during the story."],"modelAnswer":"The class listened quietly during the story."}','{"text":"Use adverbs to tell how, when or where an action happens; many manner adverbs end in -ly."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-11','P1-P4',11,'agreement','There is / there are & quantity','Match singular and plural nouns with there is/are and quantity words.','{"rule":"Use “there is” with singular/uncountable nouns and “there are” with plural count nouns.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for there is / there are & quantity.","Apply there is / there are & quantity accurately in context.","Edit a common error involving there is / there are & quantity."]','[{"label":"Accurate","sentence":"There are three books on the desk."},{"label":"Needs editing","sentence":"There is three books on the desk."},{"label":"Correction","sentence":"There are three books on the desk."}]','["Avoid: There is three books on the desk.","Prefer: There are three books on the desk."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-11-a','gram-p1p4-11','P1-P4','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “There is / there are & quantity”?","options":["There are three books on the desk.","There is three books on the desk.","There is three books on the desk.?","There are three books on the desk. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["There are three books on the desk."]}','{"text":"Use “there is” with singular/uncountable nouns and “there are” with plural count nouns."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-11-b','gram-p1p4-11','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: There is three books on the desk.","modelText":"There are three books on the desk.","speakFirst":false}','{"acceptedAnswers":["There are three books on the desk."],"modelAnswer":"There are three books on the desk."}','{"text":"Use “there is” with singular/uncountable nouns and “there are” with plural count nouns."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p1p4-12','P1-P4',12,'editing','Sentence boundaries & basic editing','Recognise complete sentences, capitals and end punctuation.','{"rule":"A complete sentence needs a clear subject and verb; separate complete ideas with correct punctuation.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for sentence boundaries & basic editing.","Apply sentence boundaries & basic editing accurately in context.","Edit a common error involving sentence boundaries & basic editing."]','[{"label":"Accurate","sentence":"We finished our work. Then we packed our bags."},{"label":"Needs editing","sentence":"we finished our work then we packed our bags"},{"label":"Correction","sentence":"We finished our work. Then we packed our bags."}]','["Avoid: we finished our work then we packed our bags","Prefer: We finished our work. Then we packed our bags."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-12-a','gram-p1p4-12','P1-P4','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Sentence boundaries & basic editing”?","options":["We finished our work. Then we packed our bags.","we finished our work then we packed our bags","we finished our work then we packed our bags?","We finished our work. Then we packed our bags. Extra."],"audioText":"We finished our work. Then we packed our bags."}','{"correctOption":0,"acceptedAnswers":["We finished our work. Then we packed our bags."]}','{"text":"A complete sentence needs a clear subject and verb; separate complete ideas with correct punctuation."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p1p4-12-b','gram-p1p4-12','P1-P4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: we finished our work then we packed our bags","modelText":"We finished our work. Then we packed our bags.","speakFirst":false}','{"acceptedAnswers":["We finished our work. Then we packed our bags."],"modelAnswer":"We finished our work. Then we packed our bags."}','{"text":"A complete sentence needs a clear subject and verb; separate complete ideas with correct punctuation."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-09','P5',9,'verbs','Gerunds & infinitives','Choose common verb + -ing and verb + to-infinitive patterns.','{"rule":"Some verbs are followed by -ing forms, while others are followed by to + base verb; learn the common patterns in context.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for gerunds & infinitives.","Apply gerunds & infinitives accurately in context.","Edit a common error involving gerunds & infinitives."]','[{"label":"Accurate","sentence":"We decided to leave early but enjoyed walking home."},{"label":"Needs editing","sentence":"We decided leaving early but enjoyed to walk home."},{"label":"Correction","sentence":"We decided to leave early but enjoyed walking home."}]','["Avoid: We decided leaving early but enjoyed to walk home.","Prefer: We decided to leave early but enjoyed walking home."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-09-a','gram-p5-09','P5','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Gerunds & infinitives”?","options":["We decided to leave early but enjoyed walking home.","We decided leaving early but enjoyed to walk home.","We decided leaving early but enjoyed to walk home.?","We decided to leave early but enjoyed walking home. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["We decided to leave early but enjoyed walking home."]}','{"text":"Some verbs are followed by -ing forms, while others are followed by to + base verb; learn the common patterns in context."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-09-b','gram-p5-09','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: We decided leaving early but enjoyed to walk home.","modelText":"We decided to leave early but enjoyed walking home.","speakFirst":false}','{"acceptedAnswers":["We decided to leave early but enjoyed walking home."],"modelAnswer":"We decided to leave early but enjoyed walking home."}','{"text":"Some verbs are followed by -ing forms, while others are followed by to + base verb; learn the common patterns in context."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-10','P5',10,'clauses','Adverbial clauses of time, reason & contrast','Link ideas using because, although, when, before, after and while.','{"rule":"Use subordinating conjunctions to show the relationship between a main clause and an adverbial clause.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for adverbial clauses of time, reason & contrast.","Apply adverbial clauses of time, reason & contrast accurately in context.","Edit a common error involving adverbial clauses of time, reason & contrast."]','[{"label":"Accurate","sentence":"Although it was raining, the match continued."},{"label":"Needs editing","sentence":"Although it was raining, but the match continued."},{"label":"Correction","sentence":"Although it was raining, the match continued."}]','["Avoid: Although it was raining, but the match continued.","Prefer: Although it was raining, the match continued."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
