INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-10-b','gram-p5-10','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: Although it was raining, but the match continued.","modelText":"Although it was raining, the match continued.","speakFirst":false}','{"acceptedAnswers":["Although it was raining, the match continued."],"modelAnswer":"Although it was raining, the match continued."}','{"text":"Use subordinating conjunctions to show the relationship between a main clause and an adverbial clause."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-11','P5',11,'punctuation','Direct speech & punctuation','Punctuate dialogue accurately with quotation marks, commas and sentence punctuation.','{"rule":"Use quotation marks around spoken words and place reporting-clause punctuation carefully.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for direct speech & punctuation.","Apply direct speech & punctuation accurately in context.","Edit a common error involving direct speech & punctuation."]','[{"label":"Accurate","sentence":"“Please wait here,” the teacher said."},{"label":"Needs editing","sentence":"“Please wait here” the teacher said."},{"label":"Correction","sentence":"“Please wait here,” the teacher said."}]','["Avoid: “Please wait here” the teacher said.","Prefer: “Please wait here,” the teacher said."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
