INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-11-b','gram-p5-11','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: “Please wait here” the teacher said.","modelText":"“Please wait here,” the teacher said.","speakFirst":false}','{"acceptedAnswers":["“Please wait here,” the teacher said."],"modelAnswer":"“Please wait here,” the teacher said."}','{"text":"Use quotation marks around spoken words and place reporting-clause punctuation carefully."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p5-12','P5',12,'noun groups','Determiners & quantifiers','Choose much, many, few, little, several, enough and each/every for the noun type and meaning.','{"rule":"Match determiners and quantifiers to countable/uncountable and singular/plural nouns.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for determiners & quantifiers.","Apply determiners & quantifiers accurately in context.","Edit a common error involving determiners & quantifiers."]','[{"label":"Accurate","sentence":"We have enough water but only a few cups."},{"label":"Needs editing","sentence":"We have enough waters but only a little cups."},{"label":"Correction","sentence":"We have enough water but only a few cups."}]','["Avoid: We have enough waters but only a little cups.","Prefer: We have enough water but only a few cups."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-12-a','gram-p5-12','P5','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Determiners & quantifiers”?","options":["We have enough water but only a few cups.","We have enough waters but only a little cups.","We have enough waters but only a little cups.?","We have enough water but only a few cups. Extra."],"audioText":"We have enough water but only a few cups."}','{"correctOption":0,"acceptedAnswers":["We have enough water but only a few cups."]}','{"text":"Match determiners and quantifiers to countable/uncountable and singular/plural nouns."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p5-12-b','gram-p5-12','P5','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: We have enough waters but only a little cups.","modelText":"We have enough water but only a few cups.","speakFirst":false}','{"acceptedAnswers":["We have enough water but only a few cups."],"modelAnswer":"We have enough water but only a few cups."}','{"text":"Match determiners and quantifiers to countable/uncountable and singular/plural nouns."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-09','P6',9,'clauses','Non-finite clauses','Use -ing, -ed and to-infinitive clauses to combine ideas concisely.','{"rule":"Non-finite clauses can reduce repeated subjects and make synthesis more concise when the implied subject is clear.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for non-finite clauses.","Apply non-finite clauses accurately in context.","Edit a common error involving non-finite clauses."]','[{"label":"Accurate","sentence":"Hearing the alarm, the pupils left the room calmly."},{"label":"Needs editing","sentence":"Hearing the alarm, the room was left calmly by the pupils."},{"label":"Correction","sentence":"Hearing the alarm, the pupils left the room calmly."}]','["Avoid: Hearing the alarm, the room was left calmly by the pupils.","Prefer: Hearing the alarm, the pupils left the room calmly."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-09-a','gram-p6-09','P6','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Non-finite clauses”?","options":["Hearing the alarm, the pupils left the room calmly.","Hearing the alarm, the room was left calmly by the pupils.","Hearing the alarm, the room was left calmly by the pupils.?","Hearing the alarm, the pupils left the room calmly. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["Hearing the alarm, the pupils left the room calmly."]}','{"text":"Non-finite clauses can reduce repeated subjects and make synthesis more concise when the implied subject is clear."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-09-b','gram-p6-09','P6','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: Hearing the alarm, the room was left calmly by the pupils.","modelText":"Hearing the alarm, the pupils left the room calmly.","speakFirst":false}','{"acceptedAnswers":["Hearing the alarm, the pupils left the room calmly."],"modelAnswer":"Hearing the alarm, the pupils left the room calmly."}','{"text":"Non-finite clauses can reduce repeated subjects and make synthesis more concise when the implied subject is clear."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-10','P6',10,'clauses','Relative-clause precision','Choose who, which, that, whose and where accurately and punctuate extra information.','{"rule":"Use relative pronouns according to the noun and decide whether the information is defining or non-defining.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for relative-clause precision.","Apply relative-clause precision accurately in context.","Edit a common error involving relative-clause precision."]','[{"label":"Accurate","sentence":"Mr Lim, who coaches the team, arrived early."},{"label":"Needs editing","sentence":"Mr Lim, which coaches the team, arrived early."},{"label":"Correction","sentence":"Mr Lim, who coaches the team, arrived early."}]','["Avoid: Mr Lim, which coaches the team, arrived early.","Prefer: Mr Lim, who coaches the team, arrived early."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-10-a','gram-p6-10','P6','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Relative-clause precision”?","options":["Mr Lim, who coaches the team, arrived early.","Mr Lim, which coaches the team, arrived early.","Mr Lim, which coaches the team, arrived early.?","Mr Lim, who coaches the team, arrived early. Extra."],"audioText":"Mr Lim, who coaches the team, arrived early."}','{"correctOption":0,"acceptedAnswers":["Mr Lim, who coaches the team, arrived early."]}','{"text":"Use relative pronouns according to the noun and decide whether the information is defining or non-defining."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-10-b','gram-p6-10','P6','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: Mr Lim, which coaches the team, arrived early.","modelText":"Mr Lim, who coaches the team, arrived early.","speakFirst":false}','{"acceptedAnswers":["Mr Lim, who coaches the team, arrived early."],"modelAnswer":"Mr Lim, who coaches the team, arrived early."}','{"text":"Use relative pronouns according to the noun and decide whether the information is defining or non-defining."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-11','P6',11,'verbs','Modal meaning & perfect modals','Express certainty, possibility, obligation and past judgement precisely.','{"rule":"Choose modals for degree of certainty/obligation; use modal + have + past participle for past possibilities or criticism.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for modal meaning & perfect modals.","Apply modal meaning & perfect modals accurately in context.","Edit a common error involving modal meaning & perfect modals."]','[{"label":"Accurate","sentence":"She might have left her book in the library."},{"label":"Needs editing","sentence":"She might has left her book in the library."},{"label":"Correction","sentence":"She might have left her book in the library."}]','["Avoid: She might has left her book in the library.","Prefer: She might have left her book in the library."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
