INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-p6-11-b','gram-p6-11','P6','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: She might has left her book in the library.","modelText":"She might have left her book in the library.","speakFirst":false}','{"acceptedAnswers":["She might have left her book in the library."],"modelAnswer":"She might have left her book in the library."}','{"text":"Choose modals for degree of certainty/obligation; use modal + have + past participle for past possibilities or criticism."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-p6-12','P6',12,'editing','Parallel structure & comparison','Keep grammatical forms parallel in lists and comparisons.','{"rule":"Items joined in a series or balanced comparison should use matching grammatical structures.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for parallel structure & comparison.","Apply parallel structure & comparison accurately in context.","Edit a common error involving parallel structure & comparison."]','[{"label":"Accurate","sentence":"The camp taught us to plan carefully, work patiently and communicate clearly."},{"label":"Needs editing","sentence":"The camp taught us to plan carefully, working patiently and clear communication."},{"label":"Correction","sentence":"The camp taught us to plan carefully, work patiently and communicate clearly."}]','["Avoid: The camp taught us to plan carefully, working patiently and clear communication.","Prefer: The camp taught us to plan carefully, work patiently and communicate clearly."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
