INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-09','S1',9,'verbs','Verb complementation','Control verb + object, verb + -ing and verb + infinitive patterns.','{"rule":"Different verbs license different complements; accurate complementation prevents common sentence-pattern errors.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for verb complementation.","Apply verb complementation accurately in context.","Edit a common error involving verb complementation."]','[{"label":"Accurate","sentence":"The coach encouraged us to practise regularly."},{"label":"Needs editing","sentence":"The coach encouraged that we to practise regularly."},{"label":"Correction","sentence":"The coach encouraged us to practise regularly."}]','["Avoid: The coach encouraged that we to practise regularly.","Prefer: The coach encouraged us to practise regularly."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s1-09-a','gram-s1-09','S1','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Verb complementation”?","options":["The coach encouraged us to practise regularly.","The coach encouraged that we to practise regularly.","The coach encouraged that we to practise regularly.?","The coach encouraged us to practise regularly. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["The coach encouraged us to practise regularly."]}','{"text":"Different verbs license different complements; accurate complementation prevents common sentence-pattern errors."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s1-09-b','gram-s1-09','S1','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: The coach encouraged that we to practise regularly.","modelText":"The coach encouraged us to practise regularly.","speakFirst":false}','{"acceptedAnswers":["The coach encouraged us to practise regularly."],"modelAnswer":"The coach encouraged us to practise regularly."}','{"text":"Different verbs license different complements; accurate complementation prevents common sentence-pattern errors."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-10','S1',10,'clauses','Relative clauses: defining & non-defining','Add essential or extra information with accurate relative forms and commas.','{"rule":"Defining clauses identify the noun; non-defining clauses add extra information and are separated by commas.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for relative clauses: defining & non-defining.","Apply relative clauses: defining & non-defining accurately in context.","Edit a common error involving relative clauses: defining & non-defining."]','[{"label":"Accurate","sentence":"The library, which was renovated last year, now has more study spaces."},{"label":"Needs editing","sentence":"The library which was renovated last year, now has more study spaces."},{"label":"Correction","sentence":"The library, which was renovated last year, now has more study spaces."}]','["Avoid: The library which was renovated last year, now has more study spaces.","Prefer: The library, which was renovated last year, now has more study spaces."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s1-10-a','gram-s1-10','S1','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Relative clauses: defining & non-defining”?","options":["The library, which was renovated last year, now has more study spaces.","The library which was renovated last year, now has more study spaces.","The library which was renovated last year, now has more study spaces.?","The library, which was renovated last year, now has more study spaces. Extra."],"audioText":"The library, which was renovated last year, now has more study spaces."}','{"correctOption":0,"acceptedAnswers":["The library, which was renovated last year, now has more study spaces."]}','{"text":"Defining clauses identify the noun; non-defining clauses add extra information and are separated by commas."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s1-10-b','gram-s1-10','S1','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: The library which was renovated last year, now has more study spaces.","modelText":"The library, which was renovated last year, now has more study spaces.","speakFirst":false}','{"acceptedAnswers":["The library, which was renovated last year, now has more study spaces."],"modelAnswer":"The library, which was renovated last year, now has more study spaces."}','{"text":"Defining clauses identify the noun; non-defining clauses add extra information and are separated by commas."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-11','S1',11,'verbs','Conditionals: real & hypothetical','Distinguish likely conditions from imagined or unlikely situations.','{"rule":"Use present + will for likely future conditions and past + would for hypothetical present/future situations.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for conditionals: real & hypothetical.","Apply conditionals: real & hypothetical accurately in context.","Edit a common error involving conditionals: real & hypothetical."]','[{"label":"Accurate","sentence":"If we leave now, we will arrive before the crowd."},{"label":"Needs editing","sentence":"If we will leave now, we arrive before the crowd."},{"label":"Correction","sentence":"If we leave now, we will arrive before the crowd."}]','["Avoid: If we will leave now, we arrive before the crowd.","Prefer: If we leave now, we will arrive before the crowd."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s1-11-a','gram-s1-11','S1','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Conditionals: real & hypothetical”?","options":["If we leave now, we will arrive before the crowd.","If we will leave now, we arrive before the crowd.","If we will leave now, we arrive before the crowd.?","If we leave now, we will arrive before the crowd. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["If we leave now, we will arrive before the crowd."]}','{"text":"Use present + will for likely future conditions and past + would for hypothetical present/future situations."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s1-11-b','gram-s1-11','S1','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: If we will leave now, we arrive before the crowd.","modelText":"If we leave now, we will arrive before the crowd.","speakFirst":false}','{"acceptedAnswers":["If we leave now, we will arrive before the crowd."],"modelAnswer":"If we leave now, we will arrive before the crowd."}','{"text":"Use present + will for likely future conditions and past + would for hypothetical present/future situations."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s1-12','S1',12,'punctuation','Punctuation for clarity','Use commas, colons, semicolons and dashes to clarify relationships between ideas.','{"rule":"Choose punctuation according to sentence structure; do not use a comma alone to join two complete sentences.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for punctuation for clarity.","Apply punctuation for clarity accurately in context.","Edit a common error involving punctuation for clarity."]','[{"label":"Accurate","sentence":"The choice was difficult; however, we had to decide."},{"label":"Needs editing","sentence":"The choice was difficult, however, we had to decide."},{"label":"Correction","sentence":"The choice was difficult; however, we had to decide."}]','["Avoid: The choice was difficult, however, we had to decide.","Prefer: The choice was difficult; however, we had to decide."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
