INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-09','S2',9,'clauses','Participle clauses','Use present and past participle clauses without dangling modifiers.','{"rule":"A participle clause normally shares its understood subject with the main clause.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for participle clauses.","Apply participle clauses accurately in context.","Edit a common error involving participle clauses."]','[{"label":"Accurate","sentence":"Concerned about the delay, the organiser called the supplier."},{"label":"Needs editing","sentence":"Concerned about the delay, the supplier was called by the organiser."},{"label":"Correction","sentence":"Concerned about the delay, the organiser called the supplier."}]','["Avoid: Concerned about the delay, the supplier was called by the organiser.","Prefer: Concerned about the delay, the organiser called the supplier."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
