INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-10','S2',10,'verbs','Reporting verbs & patterns','Report claims, advice and arguments with accurate verb patterns.','{"rule":"Reporting verbs carry stance and require different structures such as suggest + -ing/that-clause or advise + object + to-infinitive.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for reporting verbs & patterns.","Apply reporting verbs & patterns accurately in context.","Edit a common error involving reporting verbs & patterns."]','[{"label":"Accurate","sentence":"The teacher advised us to check the source."},{"label":"Needs editing","sentence":"The teacher advised that us check the source."},{"label":"Correction","sentence":"The teacher advised us to check the source."}]','["Avoid: The teacher advised that us check the source.","Prefer: The teacher advised us to check the source."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s2-10-a','gram-s2-10','S2','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Reporting verbs & patterns”?","options":["The teacher advised us to check the source.","The teacher advised that us check the source.","The teacher advised that us check the source.?","The teacher advised us to check the source. Extra."],"audioText":"The teacher advised us to check the source."}','{"correctOption":0,"acceptedAnswers":["The teacher advised us to check the source."]}','{"text":"Reporting verbs carry stance and require different structures such as suggest + -ing/that-clause or advise + object + to-infinitive."}');
