INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-11','S2',11,'noun groups','Determiners, reference & quantification','Use articles, demonstratives and quantifiers to make reference precise across a text.','{"rule":"Determiners signal whether a noun is general, specific, countable or already known to the reader.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for determiners, reference & quantification.","Apply determiners, reference & quantification accurately in context.","Edit a common error involving determiners, reference & quantification."]','[{"label":"Accurate","sentence":"Several proposals were discussed, but only one met all the requirements."},{"label":"Needs editing","sentence":"Several proposal were discussed, but only one met all requirements specific."},{"label":"Correction","sentence":"Several proposals were discussed, but only one met all the requirements."}]','["Avoid: Several proposal were discussed, but only one met all requirements specific.","Prefer: Several proposals were discussed, but only one met all the requirements."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
