INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s2-12','S2',12,'editing','Parallelism in explanations & arguments','Use parallel forms to make complex information easier to follow.','{"rule":"Coordinate words, phrases and clauses in matching grammatical forms when they have equal roles.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for parallelism in explanations & arguments.","Apply parallelism in explanations & arguments accurately in context.","Edit a common error involving parallelism in explanations & arguments."]','[{"label":"Accurate","sentence":"The policy aims to reduce waste, improve access and strengthen accountability."},{"label":"Needs editing","sentence":"The policy aims to reduce waste, improving access and accountability is strengthened."},{"label":"Correction","sentence":"The policy aims to reduce waste, improve access and strengthen accountability."}]','["Avoid: The policy aims to reduce waste, improving access and accountability is strengthened.","Prefer: The policy aims to reduce waste, improve access and strengthen accountability."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s2-12-a','gram-s2-12','S2','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Parallelism in explanations & arguments”?","options":["The policy aims to reduce waste, improve access and strengthen accountability.","The policy aims to reduce waste, improving access and accountability is strengthened.","The policy aims to reduce waste, improving access and accountability is strengthened.?","The policy aims to reduce waste, improve access and strengthen accountability. Extra."],"audioText":"The policy aims to reduce waste, improve access and strengthen accountability."}','{"correctOption":0,"acceptedAnswers":["The policy aims to reduce waste, improve access and strengthen accountability."]}','{"text":"Coordinate words, phrases and clauses in matching grammatical forms when they have equal roles."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s2-12-b','gram-s2-12','S2','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: The policy aims to reduce waste, improving access and accountability is strengthened.","modelText":"The policy aims to reduce waste, improve access and strengthen accountability.","speakFirst":false}','{"acceptedAnswers":["The policy aims to reduce waste, improve access and strengthen accountability."],"modelAnswer":"The policy aims to reduce waste, improve access and strengthen accountability."}','{"text":"Coordinate words, phrases and clauses in matching grammatical forms when they have equal roles."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-09','S3',9,'modality','Hedging & reporting stance','Use cautious language and reporting verbs to distinguish evidence from certainty.','{"rule":"Hedges such as may, appears to and suggests that reduce certainty when evidence does not justify an absolute claim.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for hedging & reporting stance.","Apply hedging & reporting stance accurately in context.","Edit a common error involving hedging & reporting stance."]','[{"label":"Accurate","sentence":"The findings suggest that the change may have improved participation."},{"label":"Needs editing","sentence":"The findings prove that the change definitely improved participation, although the evidence is limited."},{"label":"Correction","sentence":"The findings suggest that the change may have improved participation."}]','["Avoid: The findings prove that the change definitely improved participation, although the evidence is limited.","Prefer: The findings suggest that the change may have improved participation."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-09-a','gram-s3-09','S3','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Hedging & reporting stance”?","options":["The findings suggest that the change may have improved participation.","The findings prove that the change definitely improved participation, although the evidence is limited.","The findings prove that the change definitely improved participation, although the evidence is limited.?","The findings suggest that the change may have improved participation. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["The findings suggest that the change may have improved participation."]}','{"text":"Hedges such as may, appears to and suggests that reduce certainty when evidence does not justify an absolute claim."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-09-b','gram-s3-09','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: The findings prove that the change definitely improved participation, although the evidence is limited.","modelText":"The findings suggest that the change may have improved participation.","speakFirst":false}','{"acceptedAnswers":["The findings suggest that the change may have improved participation."],"modelAnswer":"The findings suggest that the change may have improved participation."}','{"text":"Hedges such as may, appears to and suggests that reduce certainty when evidence does not justify an absolute claim."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-10','S3',10,'clauses','Complex relative & non-finite structures','Compress information without creating unclear reference or dangling modifiers.','{"rule":"Use embedded relative/non-finite structures only when the referent and implied subject remain clear.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for complex relative & non-finite structures.","Apply complex relative & non-finite structures accurately in context.","Edit a common error involving complex relative & non-finite structures."]','[{"label":"Accurate","sentence":"Students seeking additional support can attend the consultation session."},{"label":"Needs editing","sentence":"Seeking additional support, the consultation session can be attended by students."},{"label":"Correction","sentence":"Students seeking additional support can attend the consultation session."}]','["Avoid: Seeking additional support, the consultation session can be attended by students.","Prefer: Students seeking additional support can attend the consultation session."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
