INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-10-b','gram-s3-10','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: Seeking additional support, the consultation session can be attended by students.","modelText":"Students seeking additional support can attend the consultation session.","speakFirst":false}','{"acceptedAnswers":["Students seeking additional support can attend the consultation session."],"modelAnswer":"Students seeking additional support can attend the consultation session."}','{"text":"Use embedded relative/non-finite structures only when the referent and implied subject remain clear."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-11','S3',11,'text','Reference chains & cohesion','Keep pronouns, substitutions and repeated key terms easy to track across paragraphs.','{"rule":"Cohesion depends on clear reference; every pronoun/substitution should have an unambiguous antecedent.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for reference chains & cohesion.","Apply reference chains & cohesion accurately in context.","Edit a common error involving reference chains & cohesion."]','[{"label":"Accurate","sentence":"The proposal has two weaknesses. These problems can be addressed through clearer rules."},{"label":"Needs editing","sentence":"The proposal has two weaknesses. They can address these through clearer rules."},{"label":"Correction","sentence":"The proposal has two weaknesses. These problems can be addressed through clearer rules."}]','["Avoid: The proposal has two weaknesses. They can address these through clearer rules.","Prefer: The proposal has two weaknesses. These problems can be addressed through clearer rules."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
