INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-11-b','gram-s3-11','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: The proposal has two weaknesses. They can address these through clearer rules.","modelText":"The proposal has two weaknesses. These problems can be addressed through clearer rules.","speakFirst":false}','{"acceptedAnswers":["The proposal has two weaknesses. These problems can be addressed through clearer rules."],"modelAnswer":"The proposal has two weaknesses. These problems can be addressed through clearer rules."}','{"text":"Cohesion depends on clear reference; every pronoun/substitution should have an unambiguous antecedent."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s3-12','S3',12,'punctuation','Punctuation for rhetorical effect','Use colons, semicolons, dashes and parentheses purposefully rather than decoratively.','{"rule":"Advanced punctuation should clarify hierarchy, emphasis or interruption while preserving grammatical structure.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for punctuation for rhetorical effect.","Apply punctuation for rhetorical effect accurately in context.","Edit a common error involving punctuation for rhetorical effect."]','[{"label":"Accurate","sentence":"One issue remains: who will be responsible for enforcement?"},{"label":"Needs editing","sentence":"One issue remains; who will be responsible for enforcement?"},{"label":"Correction","sentence":"One issue remains: who will be responsible for enforcement?"}]','["Avoid: One issue remains; who will be responsible for enforcement?","Prefer: One issue remains: who will be responsible for enforcement?"]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-12-a','gram-s3-12','S3','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Punctuation for rhetorical effect”?","options":["One issue remains: who will be responsible for enforcement?","One issue remains; who will be responsible for enforcement?","One issue remains; who will be responsible for enforcement??","One issue remains: who will be responsible for enforcement? Extra."],"audioText":"One issue remains: who will be responsible for enforcement?"}','{"correctOption":0,"acceptedAnswers":["One issue remains: who will be responsible for enforcement?"]}','{"text":"Advanced punctuation should clarify hierarchy, emphasis or interruption while preserving grammatical structure."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s3-12-b','gram-s3-12','S3','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: One issue remains; who will be responsible for enforcement?","modelText":"One issue remains: who will be responsible for enforcement?","speakFirst":false}','{"acceptedAnswers":["One issue remains: who will be responsible for enforcement?"],"modelAnswer":"One issue remains: who will be responsible for enforcement?"}','{"text":"Advanced punctuation should clarify hierarchy, emphasis or interruption while preserving grammatical structure."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-09','S4',9,'text','Ellipsis & substitution','Avoid unnecessary repetition while keeping reference clear.','{"rule":"Use substitution words such as one/ones, do/so and controlled ellipsis when the omitted material is recoverable.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for ellipsis & substitution.","Apply ellipsis & substitution accurately in context.","Edit a common error involving ellipsis & substitution."]','[{"label":"Accurate","sentence":"Some students preferred the first option; others did not."},{"label":"Needs editing","sentence":"Some students preferred the first option; others did not preferred the first option."},{"label":"Correction","sentence":"Some students preferred the first option; others did not."}]','["Avoid: Some students preferred the first option; others did not preferred the first option.","Prefer: Some students preferred the first option; others did not."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-09-a','gram-s4-09','S4','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Ellipsis & substitution”?","options":["Some students preferred the first option; others did not.","Some students preferred the first option; others did not preferred the first option.","Some students preferred the first option; others did not preferred the first option.?","Some students preferred the first option; others did not. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["Some students preferred the first option; others did not."]}','{"text":"Use substitution words such as one/ones, do/so and controlled ellipsis when the omitted material is recoverable."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-09-b','gram-s4-09','S4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: Some students preferred the first option; others did not preferred the first option.","modelText":"Some students preferred the first option; others did not.","speakFirst":false}','{"acceptedAnswers":["Some students preferred the first option; others did not."],"modelAnswer":"Some students preferred the first option; others did not."}','{"text":"Use substitution words such as one/ones, do/so and controlled ellipsis when the omitted material is recoverable."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-10','S4',10,'clauses','Embedded clauses & complex noun groups','Manage that-clauses, wh-clauses and apposition inside complex academic sentences.','{"rule":"Embedded clauses can function as subjects, objects or complements; control boundaries so the main clause remains clear.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for embedded clauses & complex noun groups.","Apply embedded clauses & complex noun groups accurately in context.","Edit a common error involving embedded clauses & complex noun groups."]','[{"label":"Accurate","sentence":"What the survey revealed was that cost mattered less than reliability."},{"label":"Needs editing","sentence":"What did the survey reveal was that cost mattered less than reliability."},{"label":"Correction","sentence":"What the survey revealed was that cost mattered less than reliability."}]','["Avoid: What did the survey reveal was that cost mattered less than reliability.","Prefer: What the survey revealed was that cost mattered less than reliability."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-10-a','gram-s4-10','S4','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Embedded clauses & complex noun groups”?","options":["What the survey revealed was that cost mattered less than reliability.","What did the survey reveal was that cost mattered less than reliability.","What did the survey reveal was that cost mattered less than reliability.?","What the survey revealed was that cost mattered less than reliability. Extra."],"audioText":"What the survey revealed was that cost mattered less than reliability."}','{"correctOption":0,"acceptedAnswers":["What the survey revealed was that cost mattered less than reliability."]}','{"text":"Embedded clauses can function as subjects, objects or complements; control boundaries so the main clause remains clear."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-10-b','gram-s4-10','S4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: What did the survey reveal was that cost mattered less than reliability.","modelText":"What the survey revealed was that cost mattered less than reliability.","speakFirst":false}','{"acceptedAnswers":["What the survey revealed was that cost mattered less than reliability."],"modelAnswer":"What the survey revealed was that cost mattered less than reliability."}','{"text":"Embedded clauses can function as subjects, objects or complements; control boundaries so the main clause remains clear."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-11','S4',11,'style','Nominalisation versus verb clarity','Choose between noun-heavy formal style and clearer verb-led sentences.','{"rule":"Nominalisation can condense ideas, but excessive noun strings hide agency; use verbs when they make the meaning clearer.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for nominalisation versus verb clarity.","Apply nominalisation versus verb clarity accurately in context.","Edit a common error involving nominalisation versus verb clarity."]','[{"label":"Accurate","sentence":"The committee evaluated the programme before deciding to expand it."},{"label":"Needs editing","sentence":"The committee conducted an evaluation of the programme prior to the making of a decision for expansion."},{"label":"Correction","sentence":"The committee evaluated the programme before deciding to expand it."}]','["Avoid: The committee conducted an evaluation of the programme prior to the making of a decision for expansion.","Prefer: The committee evaluated the programme before deciding to expand it."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-11-a','gram-s4-11','S4','reading','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Nominalisation versus verb clarity”?","options":["The committee evaluated the programme before deciding to expand it.","The committee conducted an evaluation of the programme prior to the making of a decision for expansion.","The committee conducted an evaluation of the programme prior to the making of a decision for expansion.?","The committee evaluated the programme before deciding to expand it. Extra."],"audioText":null}','{"correctOption":0,"acceptedAnswers":["The committee evaluated the programme before deciding to expand it."]}','{"text":"Nominalisation can condense ideas, but excessive noun strings hide agency; use verbs when they make the meaning clearer."}');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-11-b','gram-s4-11','S4','writing','editing','{"title":"Edit the sentence","prompt":"Correct this sentence without changing its intended meaning: The committee conducted an evaluation of the programme prior to the making of a decision for expansion.","modelText":"The committee evaluated the programme before deciding to expand it.","speakFirst":false}','{"acceptedAnswers":["The committee evaluated the programme before deciding to expand it."],"modelAnswer":"The committee evaluated the programme before deciding to expand it."}','{"text":"Nominalisation can condense ideas, but excessive noun strings hide agency; use verbs when they make the meaning clearer."}');
INSERT OR IGNORE INTO grammar_topics (id,stage,topic_order,category,title,summary,explanation_json,objectives_json,examples_json,common_mistakes_json,source_note) VALUES ('gram-s4-12','S4',12,'style','Rhetorical parallelism & emphasis','Use parallel structures, inversion and controlled repetition to strengthen formal argument.','{"rule":"Rhetorical grammar should reinforce logic and emphasis without sacrificing correctness or clarity.","whyItMatters":"This topic closes a stage-level grammar coverage gap and connects form to accurate reading, speaking and writing.","studySteps":["Read the rule and examples.","Notice the contrast between the accurate and inaccurate form.","Complete both exercises.","Revisit the topic when mastery is below 80%."]}','["Explain the key rule for rhetorical parallelism & emphasis.","Apply rhetorical parallelism & emphasis accurately in context.","Edit a common error involving rhetorical parallelism & emphasis."]','[{"label":"Accurate","sentence":"Not only does the policy reduce waste, but it also improves accountability."},{"label":"Needs editing","sentence":"Not only the policy reduces waste, but it also improves accountability."},{"label":"Correction","sentence":"Not only does the policy reduce waste, but it also improves accountability."}]','["Avoid: Not only the policy reduces waste, but it also improves accountability.","Prefer: Not only does the policy reduce waste, but it also improves accountability."]','English Mastery curriculum coverage audit; original content aligned to progressive Singapore primary/secondary English grammar learning.');
INSERT OR IGNORE INTO grammar_exercises (id,topic_id,stage,modality,exercise_type,prompt_json,answer_json,explanation_json) VALUES ('gram-s4-12-a','gram-s4-12','S4','listening','multiple_choice','{"title":"Choose the accurate sentence","prompt":"Which sentence best applies the rule for “Rhetorical parallelism & emphasis”?","options":["Not only does the policy reduce waste, but it also improves accountability.","Not only the policy reduces waste, but it also improves accountability.","Not only the policy reduces waste, but it also improves accountability.?","Not only does the policy reduce waste, but it also improves accountability. Extra."],"audioText":"Not only does the policy reduce waste, but it also improves accountability."}','{"correctOption":0,"acceptedAnswers":["Not only does the policy reduce waste, but it also improves accountability."]}','{"text":"Rhetorical grammar should reinforce logic and emphasis without sacrificing correctness or clarity."}');
